// Builds seed.sql from tools/questions.js.
//
//   node tools/seed.js
//
// Ids are derived from role, level and position, so re-running produces the
// same ids and INSERT OR REPLACE updates rows in place instead of duplicating.

import { writeFileSync } from 'node:fs';
import { QUESTIONS } from './questions.js';

const q = (value) => `'${String(value).replace(/'/g, "''")}'`;
const now = new Date().toISOString();

const lines = [
  '-- Generated by tools/seed.js. Edit tools/questions.js, not this file.',
  '',
];

const seen = new Set();
QUESTIONS.forEach((item, index) => {
  const id = `q_${item.role}_${item.level}_${String(index + 1).padStart(3, '0')}`;
  if (seen.has(id)) throw new Error(`duplicate question id: ${id}`);
  seen.add(id);

  lines.push(
    'INSERT OR REPLACE INTO questions (id, role, topic, level, prompt, model_answer, created_at) VALUES (' +
      [id, item.role, item.topic, item.level, item.prompt, item.answer, now].map(q).join(', ') +
      ');',
  );

  item.followUps.forEach((f, i) => {
    lines.push(
      'INSERT OR REPLACE INTO follow_ups (id, question_id, position, prompt, model_answer) VALUES (' +
        [q(`${id}_f${i + 1}`), q(id), i + 1, q(f.prompt), q(f.answer)].join(', ') +
        ');',
    );
  });
  lines.push('');
});

writeFileSync(new URL('../seed.sql', import.meta.url), lines.join('\n'));

const followUps = QUESTIONS.reduce((n, item) => n + item.followUps.length, 0);
console.log(`seed.sql written: ${QUESTIONS.length} questions, ${followUps} follow-ups`);
